<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue';
import { studio, dirty, saveProject } from '../stores/project-store';
import { api, downloadFrom } from '../services/local-api';
const pinned = ref(studio.revisionId), issues = ref<string[]>([]), busy = ref(false), error = ref(''), variants = ref(['landscape','portrait']);
const job = ref<{ id: string; status: string; progress?: number; error?: string; receipt?: { outputs?: { variant: string }[] } }>();
let timer: ReturnType<typeof setTimeout>, alive = true;
async function inspect() { try { issues.value = await api('/preflight','POST',{ projectId: studio.document!.id, revisionId: pinned.value }); } catch(e) { error.value = String(e); } }
async function save() { busy.value = true; try { await saveProject(); pinned.value = studio.revisionId; await inspect(); } catch(e) { error.value = String(e); } finally { busy.value = false; } }
async function start() { busy.value = true; error.value = ''; try { const result = await api<{ id: string }>('/jobs','POST',{ projectId: studio.document!.id, revisionId: pinned.value, variants: variants.value }); job.value = { id: result.id, status: 'queued', progress: 0 }; localStorage.setItem('gstory-job-' + studio.document!.id, result.id); poll(); } catch(e) { error.value = String(e); } finally { busy.value = false; } }
async function poll() { if (!alive || !job.value) return; try { job.value = await api('/jobs/' + job.value.id); if (['queued','running'].includes(job.value!.status)) timer = setTimeout(poll,700); } catch(e) { error.value = String(e); } }
async function bundle(mode: string) { busy.value = true; error.value = ''; try { await downloadFrom('/packages/' + studio.document!.id + '/' + pinned.value + '/' + mode, 'story-' + mode + '.gstory'); } catch(e) { error.value = String(e); } finally { busy.value = false; } }
onMounted(() => { void inspect(); const last = localStorage.getItem('gstory-job-' + studio.document!.id); if (last) { job.value = { id: last, status: 'loading' }; poll(); } });
onBeforeUnmount(() => { alive = false; clearTimeout(timer); });
</script>
<template><q-card class="dialog-card"><q-card-section><div class="eyebrow">Export & exchange</div><h2>Take your story with you</h2><p>Every output uses one saved revision. Changes made after this revision do not alter a running export.</p><div class="badge">Revision {{ pinned.slice(0, 12) }}</div><div v-if="dirty()" class="notice warn">There are unsaved changes.<q-btn flat label="Save and use latest" :loading="busy" @click="save" /></div></q-card-section>
<q-card-section><h3>Video</h3><p class="hint">H.264 MP4 · 30 fps · local Chromium · no account or cloud rendering</p><q-checkbox v-model="variants" val="landscape" label="Landscape · 1920 × 1080" /><q-checkbox v-model="variants" val="portrait" label="Portrait · 1080 × 1920" />
<div v-if="issues.length" class="notice warn"><b>Before video export</b><ul><li v-for="issue in issues" :key="issue">{{ issue }}</li></ul></div><div v-else class="notice good">Source, revision, and frame preflight passed.</div>
<q-btn color="primary" label="Render saved revision" :disable="!!issues.length || !variants.length || ['queued','running'].includes(job?.status ?? '')" :loading="busy" @click="start" />
<div v-if="job" class="mini-card"><b>{{ job.status }}</b><q-linear-progress :value="job.progress ?? 0" class="q-my-sm" /><p v-if="job.error" class="error">{{ job.error }}</p><q-btn v-if="['queued','running'].includes(job.status)" flat label="Cancel render" @click="api('/jobs/' + job.id + '/cancel', 'POST', {}).then(poll)" /><template v-if="job.status === 'completed'"><q-btn v-for="variant in job.receipt?.outputs?.map(output => output.variant) ?? []" :key="variant" outline class="q-mr-sm" :label="'Download ' + variant" @click="downloadFrom('/jobs/' + job.id + '/' + variant, variant + '.mp4').catch(e => error = String(e))" /></template></div></q-card-section>
<q-separator /><q-card-section><h3>Portable project</h3><p>Portable packages include all original assets only when redistribution is permitted. A reference package records omitted assets so the receiving author can supply them.</p><div class="button-row"><q-btn outline :loading="busy" label="Download portable .gstory" @click="bundle('portable')" /><q-btn flat :loading="busy" label="Download references package" @click="bundle('references')" /></div></q-card-section>
<q-card-section v-if="error"><p role="alert" class="error">{{ error }}</p></q-card-section><q-card-actions align="right"><q-btn flat label="Close" v-close-popup /></q-card-actions></q-card></template>
